'use strict';

// MODULES //

import ndarraylike2scalar from '@stdlib/ndarray-base-ndarraylike2scalar';
import getShape from '@stdlib/ndarray-base-shape';
import getStrides from '@stdlib/ndarray-base-strides';
import getOffset from '@stdlib/ndarray-base-offset';
import getData from '@stdlib/ndarray-base-data-buffer';
import { ndarray as strided } from '@stdlib/blas-ext-base-gtriu';


// MAIN //

/**
* Copies the upper triangular part of a matrix `A` to another matrix `B`.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a two-dimensional input ndarray corresponding to `A`.
*     -   a two-dimensional output ndarray corresponding to `B`.
*     -   a zero-dimensional ndarray specifying the diagonal below which to ignore.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {Object} output ndarray
*
* @example
* import matrix from '@stdlib/ndarray-matrix-ctor';
* import scalar2ndarray from '@stdlib/ndarray-from-scalar';
*
* var A = matrix( [ [ 1.0, 2.0 ], [ 3.0, 4.0 ] ], 'generic' );
* var B = matrix( [ [ 0.0, 0.0 ], [ 0.0, 0.0 ] ], 'generic' );
*
* var k = scalar2ndarray( 0, {
*     'dtype': 'generic'
* });
*
* var out = gtriu( [ A, B, k ] );
* // returns <ndarray>[ [ 1.0, 2.0 ], [ 0.0, 4.0 ] ]
*
* var bool = ( out === B );
* // returns true
*/
function gtriu( arrays ) {
	var sh;
	var sa;
	var sb;
	var A;
	var B;
	var k;

	A = arrays[ 0 ];
	B = arrays[ 1 ];
	k = ndarraylike2scalar( arrays[ 2 ] );

	sh = getShape( A, false );
	sa = getStrides( A, false );
	sb = getStrides( B, false );

	strided( sh[ 0 ], sh[ 1 ], k, getData( A ), sa[ 0 ], sa[ 1 ], getOffset( A ), getData( B ), sb[ 0 ], sb[ 1 ], getOffset( B ) ); // eslint-disable-line max-len
	return B;
}


// EXPORTS //

export default gtriu;
